"""Versioned L51 quality/gap repairs. Never rerun frozen author scripts."""
from pathlib import Path
import json,copy,hashlib,sys,datetime
R=Path(__file__).resolve().parents[1];sys.path.insert(0,str(R/'scripts'))
from authoring_helpers import DraftBatch,formula,SHA
from validate import question_hash,schema_errors,validate_bank
B='W11-L51';WHO='build_offline_study_interface:L51-v2-repair';old=json.loads((R/f'data/history/{B}/{B}-v1.json').read_text());d=copy.deepcopy(old);qs={q['id']:q for q in d['questions']};summary=json.loads((R/f'audits/{B}-contracts-review-summary.json').read_text());flags=summary['flaggedFindings'];accepted=summary['acceptedQuestionHashes'];changed=set()
for q in old['questions']:
 if q['id'] in accepted:assert question_hash(q)==accepted[q['id']]
pe=R/f'audits/{B}-primary-evidence.json';ed=json.loads(pe.read_text());eh=hashlib.sha256(pe.read_bytes()).hexdigest()
def q(n):return qs[f'{B}-Q{n:03d}']
def edit(n,opts=None,*,stem=None,why=None,typ=None,difficulty=None,steps=None,forms=None,assumptions=None):
 x=q(n);assert x['id'] in flags
 if x['id'] not in changed:
  x['version']+=1;x['status']='draft';x['reviewIds']=[];x['revisionAuthors']=list(dict.fromkeys(x.get('revisionAuthors',[])+[WHO]));changed.add(x['id'])
 if stem:x['stem']=stem
 if why:x['solution']['justification']=why;x['solution']['simpleExplanation']=why
 if typ:x['type']=typ;x['cognitiveSkill']='numerical' if typ=='numerical' else 'application' if typ in ('scenario','diagram') else 'conceptual'
 if difficulty:x['difficulty']=difficulty
 if steps is not None:x['solution']['steps']=steps
 if forms is not None:x['solution']['formulas']=forms
 if assumptions is not None:x['assumptions']=assumptions
 if opts:
  assert len(opts)==4 and len(x['correctOptionIds'])==1
  key=x['correctOptionIds'][0];ids=[key]+[o['id'] for o in x['options'] if o['id']!=key];mp=dict(zip(ids,opts))
  for o in x['options']:o['text']=mp[o['id']][0]
  x['solution']['optionExplanations']={i:v[1] for i,v in mp.items()};x['solution']['misconceptions']=[v[1] for i,v in mp.items() if i!=key]
 return x
def external(n,key):
 x=edit(n);e=ed['evidence'][key];item={'url':e['url'],'accessedAt':ed['checkedAt'],'locator':e['locator'],'savedEvidencePath':str(pe.relative_to(R)),'savedEvidenceSha256':eh,'section':key,'relationToLecture':'Supplementary qualification, not added course coverage.'}
 x.setdefault('primaryEvidence',[])
 if not any(z.get('section')==key for z in x['primaryEvidence']):x['primaryEvidence'].append(item)
 for c in x['citations']:
  if c['role']!='conflict':c['role']='premise'
def premise(n):
 for c in q(n)['citations']:
  if c['role']!='conflict':c['role']='premise'
edit(2,[('A cracked load-bearing link is a structural-body fault; voltage sag at a supply connector is a power-system fault.','The components perform mechanical support and electrical distribution respectively.'),('A cracked load-bearing link is a power-distribution fault; voltage sag at a supply connector is a structural geometry fault.','This exchanges the two component functions.'),('Both are sensor-calibration faults because they can affect measured motion.','Consequences in measurements do not reclassify the failed support and supply components.'),('Both are inference-software faults because the robot uses a controller.','The given physical failure sites do not establish a software cause.')],stem='A load-bearing link cracks, and separately a supply connector develops voltage sag. Which subsystem mapping matches the slide?',why='Classify the stated failure site: support and strength belong to structure; energy delivery belongs to power distribution.',typ='scenario');premise(2)
